// Real implementation screenshots are generated by the CI capture workflow.
// Switching previews never replaces a project screenshot with a mockup.
document.querySelectorAll(".project").forEach(project => {
  const preview = project.querySelector(".preview-frame");
  const image = preview.querySelector("img");
  const caption = preview.querySelector("figcaption");
  const controls = project.querySelectorAll(".preview-switch button");
  controls.forEach(button => {
    button.addEventListener("click", () => {
      const next = button.dataset.view;
      if (!next || preview.dataset.currentView === next) return;
      const url = next === "desktop" ? image.dataset.desktop : image.dataset.mobile;
      if (!url) return;
      const preload = new Image();
      preload.onload = () => {
        image.src = url;
        image.width = next === "desktop" ? 1440 : 390;
        image.height = next === "desktop" ? 900 : 844;
        image.alt = image.alt.replace(/Real (desktop|mobile) screenshot/i, "Real " + next + " screenshot");
        preview.dataset.currentView = next;
        caption.textContent = next === "desktop"
          ? "Live implementation capture · desktop viewport"
          : "Live implementation capture · mobile viewport";
        controls.forEach(control => {
          const active = control === button;
          control.setAttribute("aria-pressed", String(active));
          control.classList.toggle("is-active", active);
        });
      };
      preload.onerror = () => {
        // Keep the last real screenshot instead of displaying a broken image.
        console.warn("Project screenshot is unavailable:", url);
      };
      preload.src = url;
    });
  });
});
